import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.il0noOp3.js";const g=JSON.parse('{"title":"Decision record R3 — diagrams and figures","description":"Decision record R3 — how Scout produces figures. A managed PNG rasteriser, not AzViz, Graphviz, D2, or a headless browser.","frontmatter":{"description":"Decision record R3 — how Scout produces figures. A managed PNG rasteriser, not AzViz, Graphviz, D2, or a headless browser."},"headers":[],"relativePath":"design/decisions/report-diagram-rasterisation.md","filePath":"design/decisions/report-diagram-rasterisation.md"}'),i={name:"design/decisions/report-diagram-rasterisation.md"};function n(s,e,d,h,c,l){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="decision-record-r3-—-diagrams-and-figures" tabindex="-1">Decision record R3 — diagrams and figures <a class="header-anchor" href="#decision-record-r3-—-diagrams-and-figures" aria-label="Permalink to &quot;Decision record R3 — diagrams and figures&quot;">​</a></h1><blockquote><p><strong>Status:</strong> Accepted 2026-08-02. Resolves <code>AB#6737</code>, open since the diagram pipeline shipped.</p><p><strong>Epic:</strong> AB#6450 · <strong>Feature:</strong> AB#6885 · <strong>Author:</strong> Claude Code</p></blockquote><h2 id="_1-decision" tabindex="-1">1. Decision <a class="header-anchor" href="#_1-decision" aria-label="Permalink to &quot;1. Decision&quot;">​</a></h2><p><strong>Rasterise figures in managed code, with no external binary. Reject AzViz, Graphviz, D2, Mermaid-via-browser and ImageMagick for the document pipeline.</strong></p><h2 id="_2-the-problem-this-had-to-solve" tabindex="-1">2. The problem this had to solve <a class="header-anchor" href="#_2-the-problem-this-had-to-solve" aria-label="Permalink to &quot;2. The problem this had to solve&quot;">​</a></h2><p>The diagram pipeline emitted <code>.drawio</code> XML and nothing else. Phase 0 measured the consequence: <strong>0 image parts in every report across three tenants.</strong> No document could embed a figure even when one had been generated, and <code>Export-Pdf</code> shipped a 700-character warning telling the reader to open draw.io, export a JPEG by hand, and re-render.</p><h2 id="_3-why-every-dependency-based-option-was-rejected" tabindex="-1">3. Why every dependency-based option was rejected <a class="header-anchor" href="#_3-why-every-dependency-based-option-was-rejected" aria-label="Permalink to &quot;3. Why every dependency-based option was rejected&quot;">​</a></h2><p>The plan expected AzViz or D2. Both were rejected on the same test, and it is the test that matters more than the verdict:</p><blockquote><p>Scout is installed from the PowerShell Gallery and run on a laptop. <strong>A report that silently loses its figures because a native binary is missing is worse than one that never promised them</strong> — the reader cannot tell the difference between &quot;there is nothing to show&quot; and &quot;this machine could not draw it&quot;.</p></blockquote><table tabindex="0"><thead><tr><th>Option</th><th>Requires</th><th>Verdict</th></tr></thead><tbody><tr><td><strong>AzViz</strong></td><td>Graphviz on <code>PATH</code></td><td>Purpose-built for Azure topology and genuinely good. Not installed on the authoring machine, not installed on CI, and not something a module can install for a user.</td></tr><tr><td><strong>D2</strong></td><td>The <code>d2</code> binary</td><td>Best-looking output of the diagram-as-code tools. Same objection.</td></tr><tr><td><strong>draw.io export</strong></td><td>A headless browser</td><td>Bundling Chromium into a PowerShell module is not proportionate to three charts.</td></tr><tr><td><strong>ImageMagick</strong></td><td>Native install</td><td>Same objection, plus a supply-chain surface for a rasteriser.</td></tr><tr><td><strong><code>System.Drawing</code></strong></td><td>Nothing — but</td><td><code>System.Drawing.Common</code> is <strong>Windows-only from .NET 6</strong>. Scout runs wherever PowerShell 7 does.</td></tr></tbody></table><p>Confirmed empirically rather than assumed: neither <code>dot</code> nor <code>d2</code> is on <code>PATH</code> on the machine this was built on — which is precisely the situation a user will be in.</p><h2 id="_4-what-was-built-instead" tabindex="-1">4. What was built instead <a class="header-anchor" href="#_4-what-was-built-instead" aria-label="Permalink to &quot;4. What was built instead&quot;">​</a></h2><p>A PNG is a zlib stream of filtered scanlines wrapped in four chunks. <code>System.IO.Compression.DeflateStream</code> ships in the base class library and produces the raw deflate, so only the two-byte zlib header, the Adler-32 and the CRC-32 have to be written by hand. That is the entire trick, and it is why <code>src/report/Build-ScoutFigure.ps1</code> has no <code>Add-Type</code>, no P/Invoke and no <code>dotnet</code> acquire.</p><p>Text comes from a 5×7 bitmap font defined in the file. That is a deliberate ceiling: a figure label is a word or a number, and a renderer that needed real typography would need a font file, which is a dependency again.</p><h2 id="_5-what-this-does-not-do" tabindex="-1">5. What this does NOT do <a class="header-anchor" href="#_5-what-this-does-not-do" aria-label="Permalink to &quot;5. What this does NOT do&quot;">​</a></h2><p><strong>This is not a topology diagram engine.</strong> It draws the three figures the assessment report argues with — alignment by area, status composition, severity heatmap. It does not draw NIC → subnet → VNet dependency graphs, and it should not grow into something that does. The <code>.drawio</code> output stays for that job.</p><p>If enterprise topology diagrams become a requirement, that is a separate decision, and AzViz becomes the right answer <em>provided</em> the Graphviz dependency is made explicit and optional — a documented prerequisite that degrades to &quot;topology diagram not generated&quot; rather than a silent gap.</p><h2 id="_6-sources" tabindex="-1">6. Sources <a class="header-anchor" href="#_6-sources" aria-label="Permalink to &quot;6. Sources&quot;">​</a></h2><ul><li><a href="https://www.w3.org/TR/png/" target="_blank" rel="noreferrer">PNG specification, §5 (datastream) and §12 (filtering)</a></li><li><a href="https://github.com/PrateekKumarSingh/AzViz" target="_blank" rel="noreferrer">AzViz</a> · <a href="https://d2lang.com" target="_blank" rel="noreferrer">D2</a></li><li><a href="https://learn.microsoft.com/dotnet/core/compatibility/core-libraries/6.0/system-drawing-common-windows-only" target="_blank" rel="noreferrer"><code>System.Drawing.Common</code> is Windows-only</a></li></ul>',19)])])}const u=t(i,[["render",n]]);export{g as __pageData,u as default};
